"""Render the discovery trace: what was asked, what came back, and what survived.

The gap report says what the verdicts are. This says how they were reached — query by query, source
by source, claim by claim — so a reader can disagree with a specific step rather than with a
conclusion.
"""
from __future__ import annotations

from rarepipe.stages.control.discovery.compiler import DiscoveryReport


def render(report: DiscoveryReport) -> str:
    L: list[str] = []
    w = L.append
    w(f"# Capability discovery trace — {report.case_ref}")
    w("")
    w("> The model may propose where to look. The source establishes what was observed. The "
      "grounding layer establishes what may be claimed. Deterministic code establishes whether the "
      "capability satisfies the gap. A negative result is always bounded by the searched universe.")
    w("")
    w(f"Generated by `{report.discovery_compiler_version}` · discovery model "
      f"`{report.discovery_model_version}` · digest `{report.content_digest}`")
    w("")
    w("Reading order for each gap: **queries → sources → candidate claims → rejections → grounded "
      "capabilities → architecture delta.**")
    w("")

    for gap in report.gaps:
        w(f"## `{gap.gap_id}`")
        w("")
        w(f"**Required:** `{gap.required_transformation}`"
          + (f", without depending on {', '.join(f'`{d}`' for d in gap.forbidden_dependencies)}"
             if gap.forbidden_dependencies else ""))
        w("")
        w(f"**Result:** `{gap.result.value}`")
        w("")
        for provider in gap.universe_inspected:
            w(f"### Provider `{provider['provider']}`")
            w("")
            w(f"{provider['corpus']}")
            w("")
            if provider.get("accounting"):
                counts = provider["accounting"]
                w("| " + " | ".join(counts) + " |")
                w("|" + "---|" * len(counts))
                w("| " + " | ".join(str(counts[key]) for key in counts) + " |")
                w("")
            if provider.get("queries"):
                w("| Query | Looking for | Outcome | Index results | Kept |")
                w("|---|---|---|---|---|")
                for query in provider["queries"]:
                    w(f"| `{query['query']}` | {query['dimension']} | `{query['outcome']}` | "
                      f"{query['results']} | {query['selected']} |")
                w("")
            if provider["note"]:
                w(f"{provider['note']}.")
                w("")

        if gap.candidate_mechanisms_considered:
            w("### Mechanism classes and candidates considered")
            w("")
            for item in gap.candidate_mechanisms_considered:
                w(f"- {item}")
            w("")

        w("### Candidate claims, and every validator")
        w("")
        for assessment in gap.assessments:
            w(f"#### `{assessment.candidate_id}` → **{assessment.entitlement.value}**")
            w("")
            w(f"- sources: {list(assessment.source_ids)}; references "
              f"{list(assessment.references) or ['none in corpus']}")
            w(f"- causal grade: "
              f"`{assessment.causal_grade.value if assessment.causal_grade else 'not graded'}` · "
              f"causal depth {assessment.causal_depth}")
            w(f"- verification reached: "
              f"{', '.join(v.value for v in assessment.verification) or 'none'}")
            if assessment.independence:
                w(f"- independence: {assessment.independence}")
            if assessment.forbidden_hits:
                w(f"- **forbidden dependency reached:** {list(assessment.forbidden_hits)}; ancestry "
                  f"under this mechanism: {list(assessment.ancestry)}")
            for gap_object in assessment.transfer_gaps:
                w(f"- transfer gap: {gap_object.summary}")
            for check in assessment.checks:
                w(f"- `{check.validator}` {'pass' if check.passed else '**fail**'}: {check.detail}")
            w(f"- **verdict:** {assessment.reason}")
            w("")

        if gap.rejected_candidates:
            w("### Rejected, with the reason")
            w("")
            for rejected in gap.rejected_candidates:
                w(f"- `{rejected.candidate_id}` ({rejected.entity}): "
                  f"{', '.join(rejected.reasons) or 'no reason recorded'}")
            w("")
        if gap.grounded_capabilities:
            w("### Grounded capabilities")
            w("")
            for capability in gap.grounded_capabilities:
                w(f"- `{capability.capability_id}`: {capability.input} → {capability.output} "
                  f"({capability.direction.value}), `{capability.entitlement.value}`, support "
                  f"`{capability.support_level.value}`")
            w("")
        else:
            w("### Grounded capabilities")
            w("")
            w("None. Every candidate above was refused for a named reason.")
            w("")
        w(f"### Architecture delta")
        w("")
        w(f"{gap.architecture_impact}")
        w("")

    w("## Recompilation")
    w("")
    w("| Target | Before | After | Changed |")
    w("|---|---|---|---|")
    for delta in report.recompiles:
        w(f"| `{delta.target}` | `{delta.before}` | `{delta.after}` | "
          f"{'**yes**' if delta.changed else 'no'} |")
    w("")
    for delta in report.recompiles:
        w(f"- `{delta.target}`: {delta.note}")
    w("")
    w("## What this is not")
    w("")
    w(report.no_treatment_recommendation)
    w("")
    return "\n".join(L) + "\n"
